readonly rates = signal<Rate[]>([]);
private loads = 0;

/** The grade's rate in force on a date (YYYY-MM-DD), or undefined when none applies. */
inForce(grade: string, date: string): Rate | undefined {
  let found: Rate | undefined;
  for (const r of this.rates()) {
    if (r.grade === grade && (r.from === null || r.from <= date)) found = r;
  }
  return found && (found.to === null || date <= found.to) ? found : undefined;
}

/** A grade's rate in force on the sheet's today, with two decimals, or n/a when it has none. */
current(grade: string): string {
  const today = this.session.today();
  return (today ? this.inForce(grade, today)?.rate : undefined) ?? NO_RATE;
}

/** An amount in cents times the grade's rate in force on a date, divided by 100, rounded to cents as
 *  a claim dated `roundOn` rounds (half up before the policy date, else half to even), and at least the sheet's floor in force on `date` unless the amount is negative (a correction has no
 *  floor); null when no rate of the grade applies then. */
dueCents(amountCents: bigint, grade: string, date: string, roundOn: string = date): bigint | null {
  const rate = this.inForce(grade, date);
  if (rate === undefined) return null;
  const due = rounded(amountCents * hundredths(rate.rate), 10000n, this.session.roundsHalfUp(roundOn));
  if (amountCents < 0n) return due;
  const floor = hundredths(this.session.floorOn(date));
  return due < floor ? floor : due;
}

/** An amount written with two decimals times the grade's rate on a date, as `dueCents`, shown
 *  with two decimals or n/a. */
due(amount: string, grade: string, date: string): string {
  const d = this.dueCents(hundredths(amount), grade, date);
  return d === null ? NO_RATE : money(d);
}

/** Re-read the active sheet's rates from the server; an error message when that failed. */
async load(): Promise<string | null> {
  const user = this.session.user();
  const sid = this.session.sheetId();
  const load = ++this.loads;
  this.rates.set([]);
  if (!user || !sid) return null;
  try {
    const rates = await firstValueFrom(this.http.get<Rate[]>(this.url(sid), { headers: { 'X-User': user } }));
    if (load === this.loads) this.rates.set([...rates].sort(byGradeAndFrom));
    return null;
  } catch (e) {
    return failed('load', e).replace(' rate', ' rates');
  }
overdueCents(p: Person): bigint {
  return this.overdue(p).reduce((sum, c) => sum + this.figureCents(c, p), 0n);
}

/** A claim's figure: its settled due, else the figure its person's last statement bound it to (not
 *  while PENDING), else its live due at the rate in force on its date, an overdue claim's late charge on top;
 *  nothing when it has no figure. */
figureCents(c: Claim, p: Person): bigint {
  if (c.settledDue !== null) return hundredths(c.settledDue);
  const f = bound(c)
    ? (c.statedDue === null ? 0n : hundredths(c.statedDue))
    : (this.rates.dueCents(hundredths(c.amount), gradeOn(p.grades, c.date), c.date, this.claims.roundingDate(c)) ?? 0n);
  return f + this.claims.lateCents(c, f);
}

/** The grade in force on the sheet's today, the one the list shows. */
gradeToday(p: Person): string {
  const today = this.session.today();
  return today ? gradeOn(p.grades, today) : p.grade;
}

/** Each period's live due-total for each person, in cents, by period id then person id: the figures
 *  of the person's claims whose date falls in it and that counted by the status they had at the end of
 *  the period's last day, as their status log records it (one added after then does not count), and
 *  that are not left out now by a hold or a deferral — each its due as shown now: a settled claim's
 *  frozen due, else as its person's last statement bound it, else its live due, an overdue claim's
 *  late charge on top (a claim with no figure adds nothing). */
private readonly livePersonPeriodCents = computed(() => {
  const grades = new Map(this.people.people().map((p) => [p.id, p.grades]));
  const sums = new Map<number, Map<number, bigint>>();
  for (const c of this.claims.periodCandidates()) {
    const period = this.periods.of(c.date);
    if (!period || !countsAt(statusAt(c, period.to))) continue;
    let due: bigint | null;
    if (c.settledDue !== null) due = hundredths(c.settledDue);
